package com.aistock.gateway.adminmarket;
import com.aistock.common.*;import com.aistock.gateway.*;import com.aistock.gateway.security.AdminReadAccess;import com.aistock.gateway.statistics.*;import com.fasterxml.jackson.databind.ObjectMapper;import jakarta.servlet.http.Cookie;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.http.*;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class AdminMarketRefreshProxyTest {
 final String root="/api/v1/admin/market-data/SH600030/refresh-options",origin="http://127.0.0.1:15173";SchedulerPublicClient scheduler;MarketPublicClient market;StatisticsIdentityClient identity;MockMvc mvc;
 @BeforeEach void init(){scheduler=mock(SchedulerPublicClient.class);market=mock(MarketPublicClient.class);identity=mock(StatisticsIdentityClient.class);when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new StatisticsIdentityClient.Identity(UUID.randomUUID(),"ADMIN",0),"t"));when(scheduler.get(anyString(),any(),anyMap())).thenReturn(ResponseEntity.ok("{\"code\":\"OK\",\"data\":{\"queriedAt\":\"2026-10-27T12:00:00Z\",\"instrumentId\":\"SH600030\",\"actionsEnabled\":false,\"allowed\":false,\"policyVersion\":\"admin-market-refresh-v1\"}}".getBytes()));mvc=MockMvcBuilders.standaloneSetup(new AdminMarketRefreshProxyController(scheduler,new AdminReadAccess(identity,"test"),new ObjectMapper().findAndRegisterModules(),origin),new AdminMarketDataProxyController(market,new AdminReadAccess(identity,"test"),new ObjectMapper(),Clock.systemUTC())).setControllerAdvice(new ApiExceptionHandler()).addFilters(new AdminMarketRefreshCorsConfiguration().adminMarketRefreshCors(origin).getFilter()).build();}
 @Test void routesNewReadToSchedulerOnly()throws Exception{mvc.perform(get(root).cookie(new Cookie("AISTOCK_SESSION","s"))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));verify(scheduler).get(eq("admin/market-data/SH600030/refresh-options"),any(),anyMap());verifyNoInteractions(market);}
 @Test void anonymousAndUserNeverReachScheduler()throws Exception{mvc.perform(get(root)).andExpect(status().isUnauthorized());when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new StatisticsIdentityClient.Identity(UUID.randomUUID(),"USER",0),"t"));mvc.perform(get(root).cookie(new Cookie("AISTOCK_SESSION","s"))).andExpect(status().isForbidden());verifyNoInteractions(scheduler,market);}
 @Test void preflightNoIdentityAndNoDownstreamCall()throws Exception{mvc.perform(options(root.replace("refresh-options","refresh-operations")).header("Origin",origin).header("Access-Control-Request-Method","POST")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));verifyNoInteractions(identity,scheduler,market);}
 @Test void upstreamPrivateErrorHiddenWithoutRetry()throws Exception{when(scheduler.get(anyString(),any(),anyMap())).thenThrow(new IllegalStateException("private-password"));mvc.perform(get(root).cookie(new Cookie("AISTOCK_SESSION","s"))).andExpect(status().isServiceUnavailable()).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("private-password"))));verify(scheduler,times(1)).get(anyString(),any(),anyMap());}

 @Test void writesOncePreservesRefusalAndDoesNotRetryNetworkFailure()throws Exception{String op="00000000-0000-0000-0000-000000000002",version="11111111-1111-1111-1111-111111111111";var mapper=new ObjectMapper().findAndRegisterModules().disable(com.fasterxml.jackson.databind.SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);var command=new com.aistock.common.adminrefresh.AdminMarketRefreshRecords.Command(UUID.fromString(op),UUID.fromString(version),"7",LocalDate.of(2026,10,27),"RECHECK_DATA");var receipt=new com.aistock.common.adminrefresh.AdminMarketRefreshRecords.Receipt(op,"SH600030","00000000-0000-0000-0000-000000000001","REJECTED","REFRESH_ACTIONS_DISABLED",null,version,"7",null,LocalDate.of(2026,10,27),"RECHECK_DATA",Instant.parse("2026-10-27T12:00:00Z"),Instant.parse("2026-10-27T12:00:00Z"),false);when(scheduler.post(anyString(),any(),anyMap())).thenReturn(ResponseEntity.status(409).body(mapper.writeValueAsBytes(new ApiResponse<>("REFRESH_ACTIONS_DISABLED","private-error",receipt,"t"))));mvc.perform(post(root.replace("refresh-options","refresh-operations")).cookie(new Cookie("AISTOCK_SESSION","s")).header("Origin",origin).header("X-Aistock-Admin-Action","1").contentType("application/json").content(mapper.writeValueAsBytes(command))).andExpect(status().isConflict()).andExpect(jsonPath("$.data.operationId").value(op)).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("private-error"))));verify(scheduler,times(1)).post(anyString(),any(),anyMap());when(scheduler.post(anyString(),any(),anyMap())).thenThrow(new IllegalStateException("connection lost"));mvc.perform(post(root.replace("refresh-options","refresh-operations")).cookie(new Cookie("AISTOCK_SESSION","s")).header("Origin",origin).header("X-Aistock-Admin-Action","1").contentType("application/json").content(mapper.writeValueAsBytes(command))).andExpect(status().isServiceUnavailable());verify(scheduler,times(2)).post(anyString(),any(),anyMap());}
 @Test void stripsUnknownReadFieldsAndRejectsMissingContract()throws Exception{when(scheduler.get(anyString(),any(),anyMap())).thenReturn(ResponseEntity.ok("{\"code\":\"OK\",\"data\":{}}".getBytes()));mvc.perform(get(root).cookie(new Cookie("AISTOCK_SESSION","s"))).andExpect(status().isServiceUnavailable());}
}
